simStudyBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "simStudyBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "studysim",
                name = "simStudy",
                version = c(0,4,0),
                options = options,
                results = simStudyResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' Simulated study
#'
#' Simulates a plausible medical study for teaching: a clinical scenario from 
#' the library, a study design compatible with its outcome, a sample size and 
#' some realism. The dataset opens in a new window; the answer key holds the 
#' true parameters and what the design is expected to estimate.
#' 
#'
#' @examples
#' \donttest{
#' # in R, use the engine directly:
#' # sc <- studysim:::load_scenario(studysim:::builtin_library(), "chd_incidence")
#' # studysim:::simulate_study(sc, "chd", "cohort", n = 1000)
#'}
#' @param data .
#' @param libName name of the custom library file read by the Browse button
#'   (display only)
#' @param libContent base64 of the custom library file (JSON, YAML, Excel or
#'   zip)
#' @param designFilter shows in the pickers only the scenarios (and outcomes)
#'   that fit this design
#' @param scenario scenario id
#' @param outcome outcome id; empty means the scenario's first outcome
#' @param design study design; must fit the outcome
#' @param secondary adds the scenario's other outcomes as columns, for the
#'   same people (cross-sectional, cohort, prognosis and trial designs)
#' @param measured one entry per scenario variable, list(var = name, include =
#'   TRUE/FALSE, form =
#'   "continuous"/"median"/"tertiles"/"quartiles"/"quintiles"/"cuts"/"log2"/"log10"/"scale",
#'   cuts = "18.5, 25, 30" or "10\%, 90\%", or the divisor for scale, e.g.
#'   "10"); included variables are in the dataset, the others are unmeasured
#'   (they still act); form groups a continuous variable (quantiles from the
#'   sample)
#' @param n number of participants (cases plus controls in case-control
#'   designs)
#' @param ccRatio .
#' @param followup 0 uses the scenario's default
#' @param loss .
#' @param accrual 0 uses the design's default (staggered entry for prognosis)
#' @param subcohort case-cohort design, the random subcohort as a percentage
#'   of the cohort
#' @param looks randomised trial, number of equally spaced analyses (2 to 5; 0
#'   or 1 = none); adds a look column
#' @param clusters cluster randomised trial, number of clusters (randomised by
#'   cluster)
#' @param icc .
#' @param interaction 2x2 factorial trial, added to the linear predictor of
#'   those given both (beta, or log OR/HR/RR)
#' @param visits longitudinal trial, number of visits after baseline (the last
#'   one is the outcome's time)
#' @param dropout longitudinal trial, participants missing the last visit;
#'   dropout depends on the last value seen (missing at random)
#' @param regions ecological study, number of regions (rows); the sample size
#'   is not used
#' @param regionSize .
#' @param regionSd ecological study, SD of the regions' shifts of the
#'   variables (latent standard-normal scale)
#' @param contextSd ecological study, SD of an unexplained region effect on
#'   the outcome (linear predictor scale)
#' @param threshold before-after study, enrol only people whose value before
#'   is above this percentile (0 = everybody)
#' @param mcBias method comparison, constant difference B - A in the outcome's
#'   units (0 = scenario's value)
#' @param mcSlope method comparison, B per unit of the true value (1 =
#'   scenario's value)
#' @param mcErrorA method comparison, random error of A as a percentage of the
#'   outcome's SD (0 = scenario's value)
#' @param mcErrorB .
#' @param period .
#' @param carryover .
#' @param missing .
#' @param missingMech .
#' @param reliability share of the observed variance that is true variance (1
#'   = no measurement error)
#' @param misclass .
#' @param entryErrors share of numeric cells with a typing error (decimal
#'   slip, swapped digits, 999)
#' @param lodHandling assays with a limit of detection in the library (lod)
#' @param batches .
#' @param batchCv .
#' @param batchConfounded .
#' @param noiseVars .
#' @param seed .
#' @param studentKey any text (e.g. a student ID); each key gives a different
#'   dataset (capitals and surrounding spaces are ignored)
#' @param showDictionary .
#' @param showDescriptives .
#' @param showDag .
#' @param dagValues .
#' @param showKey .
#' @param openData .
#' @param exportCsv .
#' @param exportKey saves the answer key (true model, expected estimates,
#'   diagram, notes) as an HTML page for the teacher
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$notice} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$dictionary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$descriptives} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$dag} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$keyEffects} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$keyExpected} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$keyMarkers} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$keyNotes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$openState} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$csvState} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$keyState} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$dictionary$asDF}
#'
#' \code{as.data.frame(results$dictionary)}
#'
#' @export
simStudy <- function(
    data,
    libName = "",
    libContent = "",
    designFilter = "any",
    scenario = "breast_cancer_risk",
    outcome = "",
    design = "case_control",
    secondary = FALSE,
    measured = list(),
    n = 500,
    ccRatio = 1,
    followup = 0,
    loss = 2,
    accrual = 0,
    subcohort = 10,
    looks = 0,
    clusters = 20,
    icc = 0.05,
    interaction = 0,
    visits = 4,
    dropout = 20,
    regions = 30,
    regionSize = 2000,
    regionSd = 0.5,
    contextSd = 0.2,
    threshold = 0,
    mcBias = 0,
    mcSlope = 1,
    mcErrorA = 0,
    mcErrorB = 0,
    period = 0,
    carryover = 0,
    missing = 0,
    missingMech = "mcar",
    reliability = 1,
    misclass = 0,
    entryErrors = 0,
    lodHandling = "missing",
    batches = 0,
    batchCv = 15,
    batchConfounded = FALSE,
    noiseVars = 0,
    seed = 1,
    studentKey = "",
    showDictionary = TRUE,
    showDescriptives = TRUE,
    showDag = TRUE,
    dagValues = FALSE,
    showKey = FALSE,
    openData = FALSE,
    exportCsv = FALSE,
    exportKey = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("simStudy requires jmvcore to be installed (restart may be required)")

    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame())


    options <- simStudyOptions$new(
        libName = libName,
        libContent = libContent,
        designFilter = designFilter,
        scenario = scenario,
        outcome = outcome,
        design = design,
        secondary = secondary,
        measured = measured,
        n = n,
        ccRatio = ccRatio,
        followup = followup,
        loss = loss,
        accrual = accrual,
        subcohort = subcohort,
        looks = looks,
        clusters = clusters,
        icc = icc,
        interaction = interaction,
        visits = visits,
        dropout = dropout,
        regions = regions,
        regionSize = regionSize,
        regionSd = regionSd,
        contextSd = contextSd,
        threshold = threshold,
        mcBias = mcBias,
        mcSlope = mcSlope,
        mcErrorA = mcErrorA,
        mcErrorB = mcErrorB,
        period = period,
        carryover = carryover,
        missing = missing,
        missingMech = missingMech,
        reliability = reliability,
        misclass = misclass,
        entryErrors = entryErrors,
        lodHandling = lodHandling,
        batches = batches,
        batchCv = batchCv,
        batchConfounded = batchConfounded,
        noiseVars = noiseVars,
        seed = seed,
        studentKey = studentKey,
        showDictionary = showDictionary,
        showDescriptives = showDescriptives,
        showDag = showDag,
        dagValues = dagValues,
        showKey = showKey,
        openData = openData,
        exportCsv = exportCsv,
        exportKey = exportKey)

    analysis <- simStudyClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

